-- DBAS 1007 - Week 7: pixel_games sample database
-- Connect in Workbench: Host 127.0.0.1  Port 13306  User root  Password rootpassword
--
-- HOW TO USE THIS FILE
--   * Run the WHOLE file: Ctrl+Shift+Enter (the lightning bolt).
--     This is a setup script, so running everything at once is what we want.
--   * It's "rerunnable": it drops pixel_games first, so you can run it again
--     any time to get a fresh copy (handy after UPDATE / DELETE practice).
--   * Then open scripts/pixel_games_queries.sql for the demos.
--
-- Pixel Games is a (made-up) chain of 5 video game stores in Nova Scotia.
--
--   How the tables connect ( 1 --< many ):
--     platform 1--< game 1--< sale_item >--1 sale
--     customer 1--< sale        store 1--< sale        staff 1--< sale
--     store    1--< staff       store 1--< customer (home store)
--
--   Table       Rows   What's in it
--   platform        6   PC, PS5, Switch, ...
--   game           62   one row per title per platform
--   store           5   Halifax, Dartmouth, Truro, Sydney, Kentville
--   staff          21   1 Manager + 3 Associates per store, plus 1 new hire
--   customer      600   loyalty-card members
--   sale         4000   one row per checkout (Jan 2024 - Sep 2026)
--   sale_item    5963   the games on each sale
--
-- Generated by notes/build_pixel_games.py. Don't edit by hand.


DROP DATABASE IF EXISTS pixel_games;
CREATE DATABASE pixel_games;
USE pixel_games;


-- =====================================================================
-- TABLES (parents first, so the FOREIGN KEYs have something to point at)
-- =====================================================================
CREATE TABLE platform (
    platform_id  INT AUTO_INCREMENT PRIMARY KEY,
    name         VARCHAR(30)  NOT NULL UNIQUE,
    maker        VARCHAR(30)  NOT NULL,
    release_year INT          NOT NULL
);

CREATE TABLE game (
    game_id      INT AUTO_INCREMENT PRIMARY KEY,
    title        VARCHAR(100) NOT NULL,
    genre        VARCHAR(30)  NOT NULL,
    platform_id  INT          NOT NULL,
    release_year INT          NOT NULL,
    price        DECIMAL(6,2) NOT NULL,
    esrb_rating  VARCHAR(4)   NOT NULL,
    FOREIGN KEY (platform_id) REFERENCES platform (platform_id)
);

CREATE TABLE store (
    store_id     INT AUTO_INCREMENT PRIMARY KEY,
    name         VARCHAR(50)  NOT NULL,
    city         VARCHAR(40)  NOT NULL,
    opened_on    DATE         NOT NULL,
    phone        VARCHAR(20)  NOT NULL
);

CREATE TABLE staff (
    staff_id     INT AUTO_INCREMENT PRIMARY KEY,
    first_name   VARCHAR(40)  NOT NULL,
    last_name    VARCHAR(40)  NOT NULL,
    email        VARCHAR(100) NOT NULL UNIQUE,
    role         VARCHAR(20)  NOT NULL,
    store_id     INT          NOT NULL,
    hire_date    DATE         NOT NULL,
    hourly_wage  DECIMAL(5,2) NOT NULL,
    FOREIGN KEY (store_id) REFERENCES store (store_id)
);

CREATE TABLE customer (
    customer_id   INT AUTO_INCREMENT PRIMARY KEY,
    first_name    VARCHAR(40)  NOT NULL,
    last_name     VARCHAR(40)  NOT NULL,
    email         VARCHAR(100) NOT NULL UNIQUE,
    phone         VARCHAR(20),                   -- optional: some customers leave it blank (NULL)
    city          VARCHAR(40)  NOT NULL,
    province      CHAR(2)      NOT NULL,
    joined_on     DATE         NOT NULL,
    home_store_id INT          NOT NULL,
    FOREIGN KEY (home_store_id) REFERENCES store (store_id)
);

CREATE TABLE sale (
    sale_id      INT AUTO_INCREMENT PRIMARY KEY,
    customer_id  INT          NOT NULL,
    store_id     INT          NOT NULL,
    staff_id     INT          NOT NULL,
    sale_date    DATE         NOT NULL,
    FOREIGN KEY (customer_id) REFERENCES customer (customer_id),
    FOREIGN KEY (store_id)    REFERENCES store (store_id),
    FOREIGN KEY (staff_id)    REFERENCES staff (staff_id)
);

CREATE TABLE sale_item (
    sale_id      INT          NOT NULL,
    game_id      INT          NOT NULL,
    quantity     INT          NOT NULL DEFAULT 1,
    unit_price   DECIMAL(6,2) NOT NULL,          -- price paid (can be lower than game.price on sale)
    PRIMARY KEY (sale_id, game_id),
    FOREIGN KEY (sale_id) REFERENCES sale (sale_id),
    FOREIGN KEY (game_id) REFERENCES game (game_id)
);


